def calculate_flow_vector(row):
    angle_rad = math.radians(row["refracted_angle_deg"])

    # Pressure strength comes from threshold pressure + open-path resonance
    pressure_strength = row.get("threshold_pressure", 0)

    if row["gate_state"] == "pathway_open":
        pressure_strength += 0.25

    vx = round(math.cos(angle_rad) * pressure_strength, 3)
    vy = round(math.sin(angle_rad) * pressure_strength, 3)

    return pd.Series({
        "flow_x": vx,
        "flow_y": vy,
        "flow_magnitude": round(math.sqrt(vx**2 + vy**2), 3)
    })


